import React, { useState, useEffect } from 'react';
import { 
  Bus, 
  Clock, 
  ArrowRight, 
  X, 
  CheckCircle2, 
  User as UserIcon, 
  Phone, 
  Mail, 
  MapPin,
  ShieldCheck,
  CreditCard,
  Lock,
  Camera,
  History,
  Info,
  Edit3,
  Save,
  Award,
  HelpCircle
} from 'lucide-react';

const BANGLADESH_DISTRICTS = [
  'All Districts', 'Bagerhat', 'Bandarban', 'Barguna', 'Barishal', 'Bhola', 'Bogra', 'Brahmanbaria', 'Chandpur', 
  'Chittagong', 'Chuadanga', 'Comilla', 'Cox\'s Bazar', 'Dhaka', 'Dinajpur', 'Faridpur', 'Feni', 
  'Gaibandha', 'Gazipur', 'Gopalganj', 'Habiganj', 'Jamalpur', 'Jessore', 'Jhalokati', 'Jhenaidah', 
  'Joypurhat', 'Khagrachhari', 'Khulna', 'Kishoreganj', 'Kurigram', 'Kushtia', 'Lakshmipur', 'Lalmonirhat', 
  'Madaripur', 'Magura', 'Manikganj', 'Meherpur', 'Moulvibazar', 'Munshiganj', 'Mymensingh', 'Naogaon', 
  'Narail', 'Narayanganj', 'Narsingdi', 'Natore', 'Nawabganj', 'Netrokona', 'Nilphamari', 'Noakhali', 
  'Pabna', 'Panchagarh', 'Patuakhali', 'Pirojpur', 'Rajbari', 'Rajshahi', 'Rangamati', 'Rangpur', 
  'Satkhira', 'Shariatpur', 'Sherpur', 'Sirajganj', 'Sunamganj', 'Sylhet', 'Tangail', 'Thakurgaon'
];

export default function User({ activeTab = 'Home', user = {} }) {
  // Bus & Search
  const [buses, setBuses] = useState([]);
  const [searchFrom, setSearchFrom] = useState('All Districts');
  const [searchTo, setSearchTo] = useState('All Districts');
  
  // Selection & Booking
  const [selectedBus, setSelectedBus] = useState(null);
  const [selectedSeats, setSelectedSeats] = useState([]);
  const [activeImageIndex, setActiveImageIndex] = useState(0);

  // Checkout
  const [isCheckoutOpen, setIsCheckoutOpen] = useState(false);
  const [paymentMethod, setPaymentMethod] = useState('bKash');
  const [passenger, setPassenger] = useState({
    name: user?.name || '',
    phone: user?.phone || '',
    email: user?.emailOrPhone || user?.email || '',
    accountNumber: ''
  });
  const [bookingSuccess, setBookingSuccess] = useState(null);

  // User Profile States
  const [currentUserData, setCurrentUserData] = useState({
    id: user?.id || 'USR-1',
    name: user?.name || 'Passenger',
    phone: user?.phone || 'N/A',
    email: user?.emailOrPhone || user?.email || 'N/A',
    avatar: user?.avatar || '',
    password: user?.password || ''
  });

  const [isEditingProfile, setIsEditingProfile] = useState(false);
  const [editForm, setEditForm] = useState({
    name: currentUserData.name,
    phone: currentUserData.phone,
    email: currentUserData.email
  });

  const [passwordForm, setPasswordForm] = useState({ current: '', newPass: '', confirm: '' });
  const [passwordMsg, setPasswordMsg] = useState({ type: '', text: '' });
  const [paymentHistory, setPaymentHistory] = useState([]);

  // Sync Data
  const loadData = () => {
    const savedBuses = localStorage.getItem('app_buses');
    if (savedBuses) setBuses(JSON.parse(savedBuses));

    const loadedUsers = JSON.parse(localStorage.getItem('app_users') || '[]');
    const foundUser = loadedUsers.find(
      (u) => u.email === (user?.emailOrPhone || user?.email) || u.phone === user?.phone
    );

    if (foundUser) {
      setCurrentUserData((prev) => ({
        ...prev,
        ...foundUser,
        email: foundUser.email || prev.email,
        phone: foundUser.phone || prev.phone
      }));
      setEditForm({
        name: foundUser.name || '',
        phone: foundUser.phone || '',
        email: foundUser.email || ''
      });
    }

    const allTickets = JSON.parse(localStorage.getItem('app_tickets') || '[]');
    const userTickets = allTickets.filter(
      (t) => t.passengerPhone === (foundUser?.phone || user?.phone) || t.passengerName === (foundUser?.name || user?.name)
    );
    setPaymentHistory(userTickets.reverse());
  };

  useEffect(() => {
    loadData();

    const handleStorage = (e) => {
      if (e.key === 'app_buses' || e.key === 'app_tickets' || e.key === 'app_users') {
        loadData();
      }
    };
    window.addEventListener('storage', handleStorage);
    return () => window.removeEventListener('storage', handleStorage);
  }, []);

  // Filter Buses
  const filteredBuses = buses.filter((bus) => {
    const matchesFrom = searchFrom === 'All Districts' || bus.from?.toLowerCase() === searchFrom.toLowerCase();
    const matchesTo = searchTo === 'All Districts' || bus.to?.toLowerCase() === searchTo.toLowerCase();
    return matchesFrom && matchesTo;
  });

  const getNumericFare = (fareString) => {
    if (typeof fareString === 'number') return fareString;
    return parseInt(String(fareString || '0').replace(/[^0-9]/g, ''), 10) || 0;
  };

  const perSeatFare = selectedBus ? getNumericFare(selectedBus.fare) : 0;
  const totalAmount = selectedSeats.length * perSeatFare;

  // Profile Picture Upload
  const handleImageUpload = (e) => {
    const file = e.target.files[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onloadend = () => {
      const base64Image = reader.result;
      setCurrentUserData((prev) => ({ ...prev, avatar: base64Image }));

      const loadedUsers = JSON.parse(localStorage.getItem('app_users') || '[]');
      const updatedUsers = loadedUsers.map((u) => {
        if (u.email === currentUserData.email || u.phone === currentUserData.phone) {
          return { ...u, avatar: base64Image };
        }
        return u;
      });
      localStorage.setItem('app_users', JSON.stringify(updatedUsers));
    };
    reader.readAsDataURL(file);
  };

  // Save Profile Details
  const handleSaveProfileDetails = (e) => {
    e.preventDefault();
    const loadedUsers = JSON.parse(localStorage.getItem('app_users') || '[]');
    const updatedUsers = loadedUsers.map((u) => {
      if (u.email === currentUserData.email || u.phone === currentUserData.phone) {
        return { 
          ...u, 
          name: editForm.name,
          phone: editForm.phone,
          email: editForm.email
        };
      }
      return u;
    });

    localStorage.setItem('app_users', JSON.stringify(updatedUsers));
    setCurrentUserData((prev) => ({
      ...prev,
      name: editForm.name,
      phone: editForm.phone,
      email: editForm.email
    }));
    setIsEditingProfile(false);
    alert('Profile details updated successfully!');
  };

  // Change Password
  const handlePasswordChange = (e) => {
    e.preventDefault();
    setPasswordMsg({ type: '', text: '' });

    if (passwordForm.newPass.length < 4) {
      setPasswordMsg({ type: 'error', text: 'New password must be at least 4 characters long.' });
      return;
    }

    if (passwordForm.newPass !== passwordForm.confirm) {
      setPasswordMsg({ type: 'error', text: 'New passwords do not match.' });
      return;
    }

    const loadedUsers = JSON.parse(localStorage.getItem('app_users') || '[]');
    const updatedUsers = loadedUsers.map((u) => {
      if (u.email === currentUserData.email || u.phone === currentUserData.phone) {
        return { ...u, password: passwordForm.newPass };
      }
      return u;
    });

    localStorage.setItem('app_users', JSON.stringify(updatedUsers));
    setCurrentUserData((prev) => ({ ...prev, password: passwordForm.newPass }));
    setPasswordMsg({ type: 'success', text: 'Password updated successfully!' });
    setPasswordForm({ current: '', newPass: '', confirm: '' });
  };

  const handleSeatClick = (seatId, isBooked) => {
    if (isBooked) return;
    if (selectedSeats.includes(seatId)) {
      setSelectedSeats(selectedSeats.filter((id) => id !== seatId));
    } else {
      setSelectedSeats([...selectedSeats, seatId]);
    }
  };

  const handleOpenBus = (bus) => {
    setSelectedBus(bus);
    setSelectedSeats([]);
    setActiveImageIndex(0);
    setBookingSuccess(null);
  };

  const handleProceedToPayment = () => {
    if (selectedSeats.length === 0) {
      alert('Please select at least one seat to proceed!');
      return;
    }
    setIsCheckoutOpen(true);
  };

  const handleResetFilters = () => {
    setSearchFrom('All Districts');
    setSearchTo('All Districts');
  };

  const handleConfirmBooking = (e) => {
    e.preventDefault();

    if (!passenger.accountNumber) {
      alert(`Please enter your ${paymentMethod} account/card number.`);
      return;
    }

    const updatedBuses = buses.map((bus) => {
      if (bus.id === selectedBus.id) {
        const existingBooked = bus.bookedSeats || [];
        return { ...bus, bookedSeats: [...existingBooked, ...selectedSeats] };
      }
      return bus;
    });

    const trxId = 'TRX' + Math.floor(10000000 + Math.random() * 90000000);

    const newTickets = selectedSeats.map((seatId) => ({
      id: 'TICK-' + Math.floor(100000 + Math.random() * 900000),
      trxId: trxId,
      busId: selectedBus.id,
      busName: selectedBus.name,
      route: selectedBus.route || `${selectedBus.from} to ${selectedBus.to}`,
      seatNumber: seatId,
      fare: perSeatFare,
      passengerName: currentUserData.name,
      passengerPhone: currentUserData.phone,
      paymentMethod: paymentMethod,
      purchaseDate: new Date().toLocaleDateString('en-US', {
        month: 'short',
        day: 'numeric',
        year: 'numeric',
        hour: '2-digit',
        minute: '2-digit'
      })
    }));

    const savedTickets = JSON.parse(localStorage.getItem('app_tickets') || '[]');
    const updatedTickets = [...savedTickets, ...newTickets];

    localStorage.setItem('app_buses', JSON.stringify(updatedBuses));
    localStorage.setItem('app_tickets', JSON.stringify(updatedTickets));

    setBuses(updatedBuses);
    setPaymentHistory(updatedTickets.filter(
      (t) => t.passengerPhone === currentUserData.phone || t.passengerName === currentUserData.name
    ).reverse());

    setBookingSuccess({
      busName: selectedBus.name,
      seats: [...selectedSeats],
      totalPaid: totalAmount,
      trxId: trxId,
      paymentMethod
    });

    setIsCheckoutOpen(false);
    setSelectedSeats([]);

    setSelectedBus((prev) => ({
      ...prev,
      bookedSeats: [...(prev.bookedSeats || []), ...selectedSeats]
    }));
  };

  return (
    <div style={styles.container}>

      {/* 1. HOME TAB */}
      {activeTab === 'Home' && (
        <>
          <div style={styles.searchBanner}>
            <div style={styles.bannerHeader}>
              <h2 style={styles.bannerTitle}>Find & Book Bus Tickets</h2>
              <p style={styles.bannerSub}>Select your preferred route, choose your seat, and pay securely.</p>
            </div>

            <div style={styles.searchRow}>
              <div style={styles.searchField}>
                <label style={styles.searchLabel}><MapPin size={14} color="#ea580c" /> From District</label>
                <select value={searchFrom} onChange={(e) => setSearchFrom(e.target.value)} style={styles.selectInput}>
                  {BANGLADESH_DISTRICTS.map((dist) => (
                    <option key={`from-${dist}`} value={dist}>{dist}</option>
                  ))}
                </select>
              </div>

              <div style={styles.searchField}>
                <label style={styles.searchLabel}><MapPin size={14} color="#ea580c" /> To District</label>
                <select value={searchTo} onChange={(e) => setSearchTo(e.target.value)} style={styles.selectInput}>
                  {BANGLADESH_DISTRICTS.map((dist) => (
                    <option key={`to-${dist}`} value={dist}>{dist}</option>
                  ))}
                </select>
              </div>

              <button style={styles.resetSearchBtn} onClick={handleResetFilters}>
                Show All Routes
              </button>
            </div>
          </div>

          <div style={styles.sectionHeader}>
            <h3 style={styles.sectionTitle}>Available Bus Fleets ({filteredBuses.length})</h3>
            <span style={styles.liveSyncBadge}>● Live Real-Time Availability</span>
          </div>

          {filteredBuses.length === 0 ? (
            <div style={styles.emptyCard}>
              <Bus size={48} color="#71717a" />
              <p style={{ color: '#a1a1aa', margin: '8px 0 0 0' }}>No bus routes found matching your filter criteria.</p>
            </div>
          ) : (
            <div style={styles.routeGrid}>
              {filteredBuses.map((bus) => {
                const bookedCount = (bus.bookedSeats || []).length;
                const availableCount = (bus.seats || 36) - bookedCount;

                return (
                  <div key={bus.id} style={styles.busCard}>
                    <div style={styles.cardImgContainer}>
                      {bus.images && bus.images.length > 0 ? (
                        <img src={bus.images[0]} alt={bus.name} style={styles.cardImg} />
                      ) : (
                        <div style={styles.cardImgPlaceholder}>
                          <Bus size={42} color="#52525b" />
                          <span>No Photo Available</span>
                        </div>
                      )}
                      <span style={styles.busTypeBadge}>{bus.busType || 'Standard AC'}</span>
                    </div>

                    <div style={styles.cardBody}>
                      <div>
                        <span style={styles.operatorTag}>{bus.name}</span>
                        <h4 style={styles.routeTitle}>{bus.route || `${bus.from} to ${bus.to}`}</h4>
                        <span style={styles.coachNumber}>Coach No: {bus.busNumber || 'N/A'}</span>
                      </div>

                      <div style={styles.timeInfoRow}>
                        <div style={styles.timeBlock}>
                          <Clock size={13} color="#ea580c" />
                          <span>Dep: <strong>{bus.departureTime || 'N/A'}</strong></span>
                        </div>
                        <div style={styles.timeBlock}>
                          <Clock size={13} color="#ea580c" />
                          <span>Arr: <strong>{bus.arrivalTime || 'N/A'}</strong></span>
                        </div>
                      </div>

                      <div style={styles.cardFooter}>
                        <div>
                          <span style={styles.fareLabel}>Fare per seat</span>
                          <div style={styles.fareValue}>{bus.fare}</div>
                        </div>

                        <div style={{ textAlign: 'right' }}>
                          <span style={{ fontSize: '0.75rem', color: availableCount > 0 ? '#22c55e' : '#ef4444', fontWeight: '700' }}>
                            {availableCount > 0 ? `${availableCount} Seats Free` : 'Sold Out'}
                          </span>
                          <button style={styles.viewSeatsBtn} onClick={() => handleOpenBus(bus)}>
                            View Seats <ArrowRight size={14} />
                          </button>
                        </div>
                      </div>
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </>
      )}

      {/* 2. ABOUT TAB */}
      {activeTab === 'About' && (
        <div style={styles.contentSection}>
          <div style={styles.aboutHeader}>
            <Bus size={44} color="#ea580c" />
            <div>
              <h2 style={{ margin: 0, color: '#f4f4f5' }}>About Online Bus Bangladesh</h2>
              <p style={{ margin: '4px 0 0 0', color: '#a1a1aa' }}>
                Bangladesh's premier digitized inter-city transportation and instant ticket reservation portal.
              </p>
            </div>
          </div>

          {/* Mission Statement */}
          <div style={styles.aboutBannerBox}>
            <Info size={24} color="#38bdf8" style={{ minWidth: '24px' }} />
            <p style={{ margin: 0, color: '#d4d4d8', fontSize: '0.9rem', lineHeight: '1.5' }}>
              Our platform connects travelers across all 64 districts in Bangladesh with top bus operators. We strive to bring hassle-free booking, transparent seat mapping, real-time ticket availability, and guaranteed payment protection to every journey.
            </p>
          </div>

          {/* Expanded Features */}
          <div style={styles.aboutGrid}>
            <div style={styles.aboutCard}>
              <ShieldCheck size={32} color="#22c55e" />
              <h4 style={styles.aboutCardTitle}>100% Verified Fleet Operators</h4>
              <p style={styles.aboutCardText}>
                We partner with accredited bus companies like Shamoli, Ena, Hanif, and Green Line. Seat inventories sync in real-time so double booking is impossible.
              </p>
            </div>

            <div style={styles.aboutCard}>
              <CreditCard size={32} color="#ea580c" />
              <h4 style={styles.aboutCardTitle}>Instant Mobile Payment</h4>
              <p style={styles.aboutCardText}>
                Complete transactions in seconds using bKash, Nagad, Rocket, or direct debit/credit cards with immediate SMS and digital ticket confirmations.
              </p>
            </div>

            <div style={styles.aboutCard}>
              <Award size={32} color="#eab308" />
              <h4 style={styles.aboutCardTitle}>Transparent Fare Guarantee</h4>
              <p style={styles.aboutCardText}>
                No hidden service charges or unexpected surge prices at the counter. The price shown on screen is the exact fare charged to your wallet.
              </p>
            </div>

            <div style={styles.aboutCard}>
              <HelpCircle size={32} color="#38bdf8" />
              <h4 style={styles.aboutCardTitle}>24/7 Dedicated Support</h4>
              <p style={styles.aboutCardText}>
                Need to modify your seat, check trip delays, or request a refund? Our support team is online round-the-clock to keep your journey smooth.
              </p>
            </div>
          </div>
        </div>
      )}

      {/* 3. PROFILE TAB */}
      {activeTab === 'Profile' && (
        <div style={styles.contentSection}>
          <h2 style={{ margin: '0 0 20px 0', color: '#f4f4f5' }}>User Profile Management</h2>

          <div style={styles.profileTwoColumn}>
            {/* Left: Avatar & Editable Personal Info */}
            <div style={styles.profileCard}>
              <div style={styles.avatarWrapper}>
                {currentUserData.avatar ? (
                  <img src={currentUserData.avatar} alt="Profile" style={styles.avatarImg} />
                ) : (
                  <div style={styles.avatarPlaceholder}>
                    <UserIcon size={56} color="#71717a" />
                  </div>
                )}
                <label htmlFor="avatar-upload" style={styles.cameraBadge} title="Upload Photo">
                  <Camera size={14} color="#ffffff" />
                </label>
                <input 
                  id="avatar-upload" 
                  type="file" 
                  accept="image/*" 
                  onChange={handleImageUpload} 
                  style={{ display: 'none' }} 
                />
              </div>

              <h3 style={{ margin: '14px 0 2px 0', color: '#f4f4f5', textAlign: 'center' }}>{currentUserData.name}</h3>
              <span style={{ fontSize: '0.8rem', color: '#ea580c', fontWeight: '600', textAlign: 'center', display: 'block', marginBottom: '16px' }}>
                Verified Passenger
              </span>

              {/* View vs Edit Toggle Form */}
              {!isEditingProfile ? (
                <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
                  <div style={styles.infoList}>
                    <div style={styles.infoItem}>
                      <UserIcon size={16} color="#a1a1aa" />
                      <span><strong>Name:</strong> {currentUserData.name}</span>
                    </div>
                    <div style={styles.infoItem}>
                      <Mail size={16} color="#a1a1aa" />
                      <span><strong>Email:</strong> {currentUserData.email}</span>
                    </div>
                    <div style={styles.infoItem}>
                      <Phone size={16} color="#a1a1aa" />
                      <span><strong>Phone:</strong> {currentUserData.phone}</span>
                    </div>
                  </div>

                  <button style={styles.editProfileBtn} onClick={() => setIsEditingProfile(true)}>
                    <Edit3 size={15} /> Edit Personal Details
                  </button>
                </div>
              ) : (
                <form onSubmit={handleSaveProfileDetails} style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
                  <div style={styles.fieldGroup}>
                    <label style={styles.modalLabel}>Full Name</label>
                    <input 
                      type="text" 
                      value={editForm.name} 
                      onChange={(e) => setEditForm({ ...editForm, name: e.target.value })} 
                      style={styles.modalInput} 
                      required 
                    />
                  </div>

                  <div style={styles.fieldGroup}>
                    <label style={styles.modalLabel}>Email Address</label>
                    <input 
                      type="email" 
                      value={editForm.email} 
                      onChange={(e) => setEditForm({ ...editForm, email: e.target.value })} 
                      style={styles.modalInput} 
                      required 
                    />
                  </div>

                  <div style={styles.fieldGroup}>
                    <label style={styles.modalLabel}>Phone Number</label>
                    <input 
                      type="text" 
                      value={editForm.phone} 
                      onChange={(e) => setEditForm({ ...editForm, phone: e.target.value })} 
                      style={styles.modalInput} 
                      required 
                    />
                  </div>

                  <div style={{ display: 'flex', gap: '8px', marginTop: '6px' }}>
                    <button type="submit" style={styles.saveProfileBtn}>
                      <Save size={15} /> Save
                    </button>
                    <button type="button" style={styles.cancelProfileBtn} onClick={() => setIsEditingProfile(false)}>
                      Cancel
                    </button>
                  </div>
                </form>
              )}
            </div>

            {/* Right: Security Settings */}
            <div style={styles.profileCard}>
              <h3 style={{ margin: '0 0 16px 0', color: '#f4f4f5', display: 'flex', alignItems: 'center', gap: '8px' }}>
                <Lock size={18} color="#ea580c" /> Change Account Password
              </h3>

              {passwordMsg.text && (
                <div style={{
                  padding: '10px 14px',
                  borderRadius: '8px',
                  fontSize: '0.85rem',
                  marginBottom: '16px',
                  backgroundColor: passwordMsg.type === 'success' ? '#14532d' : '#7f1d1d',
                  color: passwordMsg.type === 'success' ? '#4ade80' : '#fca5a5'
                }}>
                  {passwordMsg.text}
                </div>
              )}

              <form onSubmit={handlePasswordChange} style={{ display: 'flex', flexDirection: 'column', gap: '14px' }}>
                <div style={styles.fieldGroup}>
                  <label style={styles.modalLabel}>New Password</label>
                  <input 
                    type="password" 
                    placeholder="Enter new password" 
                    value={passwordForm.newPass}
                    onChange={(e) => setPasswordForm({ ...passwordForm, newPass: e.target.value })}
                    style={styles.modalInput}
                    required
                  />
                </div>

                <div style={styles.fieldGroup}>
                  <label style={styles.modalLabel}>Confirm New Password</label>
                  <input 
                    type="password" 
                    placeholder="Confirm new password" 
                    value={passwordForm.confirm}
                    onChange={(e) => setPasswordForm({ ...passwordForm, confirm: e.target.value })}
                    style={styles.modalInput}
                    required
                  />
                </div>

                <button type="submit" style={styles.submitModalBtn}>
                  Update Password
                </button>
              </form>
            </div>
          </div>
        </div>
      )}

      {/* 4. PAYMENT TAB */}
      {activeTab === 'Payment' && (
        <div style={styles.contentSection}>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '20px' }}>
            <div>
              <h2 style={{ margin: 0, color: '#f4f4f5' }}>Payment & Transaction History</h2>
              <p style={{ margin: '4px 0 0 0', color: '#a1a1aa', fontSize: '0.85rem' }}>
                Complete archive of your seat reservations and payments made.
              </p>
            </div>
          </div>

          {paymentHistory.length === 0 ? (
            <div style={styles.emptyCard}>
              <History size={48} color="#71717a" />
              <p style={{ color: '#a1a1aa', margin: '8px 0 0 0' }}>No payment records found for your account.</p>
            </div>
          ) : (
            <div style={styles.tableWrapper}>
              <table style={styles.table}>
                <thead>
                  <tr style={styles.tableHeaderRow}>
                    <th style={styles.th}>Transaction ID</th>
                    <th style={styles.th}>Operator / Route</th>
                    <th style={styles.th}>Seat No</th>
                    <th style={styles.th}>Payment Method</th>
                    <th style={styles.th}>Date & Time</th>
                    <th style={styles.th}>Fare Paid</th>
                  </tr>
                </thead>
                <tbody>
                  {paymentHistory.map((item, idx) => (
                    <tr key={idx} style={styles.tableRow}>
                      <td style={styles.td}>
                        <span style={{ color: '#ea580c', fontWeight: '700' }}>{item.trxId || item.id}</span>
                      </td>
                      <td style={styles.td}>
                        <div style={{ fontWeight: '700', color: '#f4f4f5' }}>{item.busName}</div>
                        <div style={{ fontSize: '0.75rem', color: '#a1a1aa' }}>{item.route}</div>
                      </td>
                      <td style={styles.td}>
                        <span style={styles.seatPill}>{item.seatNumber}</span>
                      </td>
                      <td style={styles.td}>
                        <span style={{ fontWeight: '600', color: '#38bdf8' }}>{item.paymentMethod}</span>
                      </td>
                      <td style={styles.td}>{item.purchaseDate}</td>
                      <td style={styles.td}>
                        <span style={{ color: '#22c55e', fontWeight: '800' }}>৳{item.fare}</span>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      )}

      {/* SEAT SELECTION MODAL */}
      {selectedBus && (
        <div style={styles.modalOverlay} onClick={() => setSelectedBus(null)}>
          <div style={styles.modalContentLarge} onClick={(e) => e.stopPropagation()}>
            <div style={styles.modalHeader}>
              <div>
                <h3 style={{ margin: 0, color: '#ea580c', fontSize: '1.3rem' }}>{selectedBus.name}</h3>
                <span style={{ fontSize: '0.85rem', color: '#a1a1aa' }}>
                  Route: {selectedBus.route || `${selectedBus.from} to ${selectedBus.to}`} | Coach: {selectedBus.busNumber}
                </span>
              </div>
              <button style={styles.closeBtn} onClick={() => setSelectedBus(null)}><X size={20} /></button>
            </div>

            {bookingSuccess && (
              <div style={styles.successReceipt}>
                <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
                  <CheckCircle2 size={24} color="#22c55e" />
                  <div>
                    <h4 style={{ margin: 0, color: '#22c55e' }}>Booking Confirmed!</h4>
                    <p style={{ margin: '2px 0 0 0', fontSize: '0.85rem', color: '#d4d4d8' }}>
                      Transaction ID: <strong>{bookingSuccess.trxId}</strong> | Paid <strong>৳{bookingSuccess.totalPaid}</strong> via {bookingSuccess.paymentMethod}
                    </p>
                  </div>
                </div>
              </div>
            )}

            <div style={styles.modalTwoColumn}>
              <div style={styles.leftSeatColumn}>
                <div style={styles.seatHeaderFlex}>
                  <h4 style={{ margin: 0, color: '#f4f4f5', fontSize: '0.95rem' }}>Select Seats</h4>
                  <div style={styles.legendRow}>
                    <div style={styles.legendItem}><div style={{ ...styles.legendBox, backgroundColor: '#22c55e' }}></div><span>Free</span></div>
                    <div style={styles.legendItem}><div style={{ ...styles.legendBox, backgroundColor: '#ea580c' }}></div><span>Selected</span></div>
                    <div style={styles.legendItem}><div style={{ ...styles.legendBox, backgroundColor: '#6b7280' }}></div><span>Booked</span></div>
                  </div>
                </div>

                <div style={styles.busChassis}>
                  <div style={styles.driverCabinRow}>
                    <span style={styles.driverIconBadge}>🚌 Driver Cabin</span>
                    <div style={styles.steeringWheel}>⭕</div>
                  </div>

                  <div style={styles.verticalSeatContainer}>
                    {Array.from({ length: Math.ceil((selectedBus.seats || 36) / 4) }).map((_, rowIndex) => {
                      const rowLetter = String.fromCharCode(65 + rowIndex);
                      const s1 = `${rowLetter}1`;
                      const s2 = `${rowLetter}2`;
                      const s3 = `${rowLetter}3`;
                      const s4 = `${rowLetter}4`;

                      const isBooked = (seatId) => (selectedBus.bookedSeats || []).includes(seatId);
                      const isSelected = (seatId) => selectedSeats.includes(seatId);

                      const getSeatBg = (seatId) => {
                        if (isBooked(seatId)) return '#6b7280';
                        if (isSelected(seatId)) return '#ea580c';
                        return '#22c55e';
                      };

                      return (
                        <div key={rowLetter} style={styles.busRowGroup}>
                          <div style={styles.seatPair}>
                            {[s1, s2].map((seatId) => (
                              <div
                                key={seatId}
                                onClick={() => handleSeatClick(seatId, isBooked(seatId))}
                                style={{
                                  ...styles.compactSeat,
                                  backgroundColor: getSeatBg(seatId),
                                  cursor: isBooked(seatId) ? 'not-allowed' : 'pointer'
                                }}
                              >
                                {seatId}
                              </div>
                            ))}
                          </div>
                          <div style={styles.aisleGap} />
                          <div style={styles.seatPair}>
                            {[s3, s4].map((seatId) => (
                              <div
                                key={seatId}
                                onClick={() => handleSeatClick(seatId, isBooked(seatId))}
                                style={{
                                  ...styles.compactSeat,
                                  backgroundColor: getSeatBg(seatId),
                                  cursor: isBooked(seatId) ? 'not-allowed' : 'pointer'
                                }}
                              >
                                {seatId}
                              </div>
                            ))}
                          </div>
                        </div>
                      );
                    })}
                  </div>
                </div>
              </div>

              <div style={styles.rightInfoColumn}>
                <div style={styles.imageGalleryContainer}>
                  {selectedBus.images && selectedBus.images.length > 0 ? (
                    <div>
                      <img src={selectedBus.images[activeImageIndex] || selectedBus.images[0]} alt="Bus Preview" style={styles.mainLargeImg} />
                    </div>
                  ) : (
                    <div style={styles.largeImgPlaceholder}><Bus size={50} color="#52525b" /></div>
                  )}
                </div>

                <div style={styles.fareSummaryBox}>
                  <h4 style={{ margin: '0 0 10px 0', color: '#f4f4f5', fontSize: '0.95rem' }}>Fare Calculation</h4>
                  <div style={styles.summaryRow}><span>Seats:</span><span style={{ color: '#ea580c', fontWeight: '700' }}>{selectedSeats.join(', ') || 'None'}</span></div>
                  <div style={styles.summaryRow}><span>Total:</span><span style={{ fontSize: '1.2rem', fontWeight: '800', color: '#22c55e' }}>৳ {totalAmount}</span></div>
                  <button 
                    style={{ ...styles.checkoutBtn, backgroundColor: selectedSeats.length > 0 ? '#ea580c' : '#3f3f46' }}
                    disabled={selectedSeats.length === 0}
                    onClick={handleProceedToPayment}
                  >
                    <CreditCard size={18} /> Proceed to Payment
                  </button>
                </div>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* PAYMENT CHECKOUT MODAL */}
      {isCheckoutOpen && (
        <div style={styles.modalOverlay}>
          <div style={{ ...styles.modalContent, maxWidth: '520px' }}>
            <div style={styles.modalHeader}>
              <h3 style={{ margin: 0, color: '#f4f4f5' }}>Payment Gateway</h3>
              <button style={styles.closeBtn} onClick={() => setIsCheckoutOpen(false)}><X size={20} /></button>
            </div>

            <form onSubmit={handleConfirmBooking} style={styles.modalForm}>
              <div style={styles.fieldGroup}>
                <label style={styles.modalLabel}>Payment Option</label>
                <div style={styles.paymentMethodGrid}>
                  {['bKash', 'Nagad', 'Rocket', 'Card'].map((method) => (
                    <div 
                      key={method}
                      style={{
                        ...styles.paymentOptionCard,
                        borderColor: paymentMethod === method ? '#ea580c' : '#3f3f46'
                      }}
                      onClick={() => setPaymentMethod(method)}
                    >
                      <span style={{ fontWeight: '700', color: paymentMethod === method ? '#ea580c' : '#f4f4f5' }}>{method}</span>
                    </div>
                  ))}
                </div>
              </div>

              <div style={styles.fieldGroup}>
                <label style={styles.modalLabel}>Account / Phone / Card Number</label>
                <input 
                  type="text" 
                  placeholder="017XXXXXXXX" 
                  value={passenger.accountNumber} 
                  onChange={(e) => setPassenger({ ...passenger, accountNumber: e.target.value })}
                  style={styles.modalInput}
                  required
                />
              </div>

              <div style={styles.finalPaySummary}>
                <div>Total Payable:</div>
                <div style={{ fontSize: '1.2rem', color: '#22c55e', fontWeight: '800' }}>৳ {totalAmount}</div>
              </div>

              <button type="submit" style={styles.submitModalBtn}>Pay ৳ {totalAmount} & Confirm</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

